// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash, address actor) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // The reference records the target as the NEXT block: settling in
        // the immediately following block must revert (target block not yet passed).
        vm.roll(block.number + 1);

        vm.prank(actor);
        bool settled;
        try c.settle() {
            settled = true;
        } catch {
            settled = false;
        }
        assertTrue(!settled);
    }
}
